const body = $input.item.json.body || $input.item.json;

// 1. Validate required fields
const validProjects = {
  "atlas": "Projects/Atlas/logs",
  "courses": "Courses",
  "dzen": "Projects/Dzen/logs",
  "nastya": "Projects/Nastya/logs",
  "dacha": "Projects/Dacha/logs",
  "other": "Projects/Other/logs"
};

const rawProj = (body.project_id || body.project || 'atlas').toString().toLowerCase().trim();
const projectId = validProjects[rawProj] ? rawProj : 'other';
const basePath = validProjects[projectId];

const summary = body.summary || 'Автоматический отчёт о выполнении задачи';
const completedActions = Array.isArray(body.completed_actions) ? body.completed_actions : (body.completed_actions ? [body.completed_actions] : []);
const pendingActions = Array.isArray(body.pending_actions) ? body.pending_actions : [];
const filesModified = Array.isArray(body.files_modified) ? body.files_modified : [];
const decisionsMade = Array.isArray(body.decisions_made) ? body.decisions_made : [];
const newFacts = Array.isArray(body.new_facts) ? body.new_facts : [];
const newQuestions = Array.isArray(body.new_questions) ? body.new_questions : [];
const constraintsDiscovered = Array.isArray(body.constraints_discovered) ? body.constraints_discovered : [];
const nextStep = body.next_step || 'Продолжить выполнение по плану проекта.';
const sourceAi = (body.source_ai || body.source || 'ai-assistant').replace(/[^a-zA-Z0-9_-]/g, '_');
const taskId = body.task_id || ('task-' + Date.now());

// 2. Format Timestamp
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const tsStr = `${now.getUTCFullYear()}${pad(now.getUTCMonth()+1)}${pad(now.getUTCDate())}-${pad(now.getUTCHours())}${pad(now.getUTCMinutes())}${pad(now.getUTCSeconds())}`;
const isoDate = now.toISOString();

// 3. Build Log Markdown
let md = `# Отчёт о выполнении: ${projectId.toUpperCase()} (${taskId})\n\n`;
md += `**Дата:** ${isoDate}\n`;
md += `**Исполнитель (ИИ):** ${sourceAi}\n`;
md += `**Проект:** \`${projectId}\`\n`;
md += `**ID задачи:** \`${taskId}\`\n\n`;
md += `---\n\n`;

md += `## 1. Резюме сессии\n${summary}\n\n`;

md += `## 2. Выполненные действия\n`;
if (completedActions.length === 0) {
  md += `- Действия зафиксированы в диалоге\n`;
} else {
  for (const act of completedActions) {
    md += `- [x] ${act}\n`;
  }
}
md += `\n`;

if (pendingActions.length > 0) {
  md += `## 3. Незавершённые действия\n`;
  for (const act of pendingActions) {
    md += `- [ ] ${act}\n`;
  }
  md += `\n`;
}

if (decisionsMade.length > 0) {
  md += `## 4. Принятые решения\n`;
  for (const d of decisionsMade) {
    const title = typeof d === 'string' ? d : (d.title || d.id || JSON.stringify(d));
    md += `- **${title}**${d.description ? ': ' + d.description : ''}\n`;
  }
  md += `\n`;
}

if (filesModified.length > 0) {
  md += `## 5. Изменённые файлы\n`;
  for (const f of filesModified) {
    md += `- \`${f}\`\n`;
  }
  md += `\n`;
}

if (newFacts.length > 0) {
  md += `## 6. Новые подтверждённые факты\n`;
  for (const fact of newFacts) {
    md += `- ${fact}\n`;
  }
  md += `\n`;
}

if (newQuestions.length > 0) {
  md += `## 7. Открытые вопросы\n`;
  for (const q of newQuestions) {
    md += `- ? ${q}\n`;
  }
  md += `\n`;
}

if (constraintsDiscovered.length > 0) {
  md += `## 8. Обнаруженные ограничения\n`;
  for (const c of constraintsDiscovered) {
    md += `- ! ${c}\n`;
  }
  md += `\n`;
}

md += `## 9. Следующий конкретный шаг (Next Step)\n${nextStep}\n\n`;

if (body.suggested_handoff) {
  md += `## 10. Обновлённый Handoff\n${body.suggested_handoff}\n\n`;
}

// Target file path
const filename = `${tsStr}-${sourceAi}-${taskId}.md`;
const logPath = `${basePath}/${filename}`;
const base64Content = Buffer.from(md, 'utf-8').toString('base64');

return [{
  json: {
    projectId,
    taskId,
    sourceAi,
    tsStr,
    isoDate,
    logPath,
    filename,
    base64Content,
    commitMessage: `auto(ai-os): reverse-save report for ${projectId} [${taskId}]`,
    markdownLength: md.length,
    summary,
    nextStep
  }
}];

const prev = $('Validate and Format Report').first().json;
const resp = $input.item.json;

const statusCode = resp.statusCode || (resp.status ? parseInt(resp.status) : 200);
const body = resp.body || {};

if (statusCode >= 200 && statusCode < 300) {
  return [{
    json: {
      success: true,
      project_id: prev.projectId,
      task_id: prev.taskId,
      source_ai: prev.sourceAi,
      log_path: prev.logPath,
      commit_sha: body.commit ? body.commit.sha : (body.content ? body.content.sha : 'ok'),
      file_url: body.content ? body.content.html_url : `https://github.com/takeprofit83/second-brain/blob/main/${prev.logPath}`,
      timestamp: prev.isoDate,
      summary: prev.summary,
      next_step: prev.nextStep,
      message: `Отчёт успешно сохранён в Second Brain: ${prev.logPath}`
    }
  }];
} else {
  return [{
    json: {
      success: false,
      statusCode: statusCode,
      error: body.message || 'Ошибка сохранения отчёта в GitHub',
      project_id: prev.projectId,
      log_path: prev.logPath
    }
  }];
}
